import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
capacity = None
for rec in records:
    vals = rec.get('values', {})
    if 'Capacity' in vals:
        capacity = int(vals['Capacity'])
        break
if capacity is None:
    raise ValueError('No capacity found in LEGACY_RECORDS.')
products = []
value = {}
weight = {}
for rec in records:
    vals = rec.get('values', {})
    pname = vals.get('ProductName')
    if pname is not None:
        products.append(pname)
        if 'Value' not in vals or 'Weight' not in vals:
            raise ValueError(f'Missing Value or Weight for product {pname}')
        value[pname] = int(vals['Value'])
        weight[pname] = int(vals['Weight'])
if not products:
    raise ValueError('No products found in LEGACY_RECORDS.')
m = gp.Model('SupermarketStock')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in products)) <= capacity, name='cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')